import type { SVGProps } from "react";

export interface JiddahLogoProps extends SVGProps<SVGSVGElement> {
  /** Logo green. Default #039D4A */
  color?: string;
  /** Colour of the white areas inside the logo. Use "transparent" to knock them out. */
  paper?: string;
  /** Accessible name. */
  title?: string;
}

export function JiddahLogo({
  color = "#039D4A",
  paper = "#ffffff",
  title = "Jiddah Islamic Nur. & Pri. Day and Boarding School",
  ...props
}: JiddahLogoProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={VIEWBOX}
      role="img"
      aria-label={title}
      {...props}
    >
      <title>{title}</title>
      <path fill={paper} stroke={paper} strokeWidth="0.8" strokeLinejoin="round" d={WHITE_PATH} />
      <path fill={color} fillRule="evenodd" d={GREEN_PATH} />
    </svg>
  );
}

export default JiddahLogo;
